/** StockFlow integralmente implementado em Java, com Swing e SQLite JDBC. */
public final class StockFlowApp extends JFrame {
    private final StockService service = new StockService();
    private final Map<String, JTable> grids = new LinkedHashMap<>();
    private static final String[] CATEGORIES = {"MEAT", "FRUIT", "LEGUME", "GREENS", "DAIRY", "CEREAL"};

    public StockFlowApp() {
        super("StockFlow - Controle de Estoque");
        setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
        setSize(1380, 820); setMinimumSize(new Dimension(1080, 650)); setLocationRelativeTo(null);
        JPanel root = new JPanel(new BorderLayout(8, 8)); root.setBorder(BorderFactory.createEmptyBorder(12, 14, 12, 14));
        JLabel title = new JLabel("StockFlow  |  Controle de Estoque"); title.setFont(title.getFont().deriveFont(Font.BOLD, 23f)); root.add(title, BorderLayout.NORTH);
        JTabbedPane tabs = new JTabbedPane();
        addTab(tabs, "Visao geral", "overview", new String[]{"Atualizar", "Exportar CSV"}, new Runnable[]{this::refreshAll, this::exportInventory});
        addTab(tabs, "Produtos", "products", new String[]{"Cadastrar", "Editar", "Reativar (5s)", "Desativar", "Atualizar"}, new Runnable[]{this::addProduct, this::editProduct, this::reactivateProduct, this::deactivateProduct, this::refreshAll});
        addTab(tabs, "Fornecedores", "suppliers", new String[]{"Cadastrar", "Editar", "Solicitar reposicao", "Atualizar"}, new Runnable[]{this::addSupplier, this::editSupplier, this::requestReplenishment, this::refreshAll});
        addTab(tabs, "Entradas e saidas", "stock", new String[]{"Registrar entrada", "Registrar saida", "Atualizar"}, new Runnable[]{this::receipt, this::issue, this::refreshAll});
        addTab(tabs, "Reservas", "reservations", new String[]{"Nova reserva", "Confirmar saida", "Cancelar", "Atualizar"}, new Runnable[]{this::addReservation, this::confirmReservation, this::cancelReservation, this::refreshAll});
        addTab(tabs, "Bloqueios operacionais", "blocks", new String[]{"Criar bloqueio", "Liberar bloqueio", "Atualizar"}, new Runnable[]{this::addBlock, this::releaseBlock, this::refreshAll});
        addTab(tabs, "Bloqueios fisicos", "holds", new String[]{"Criar bloqueio fisico", "Liberar bloqueio fisico", "Atualizar"}, new Runnable[]{this::addHold, this::releaseHold, this::refreshAll});
        addTab(tabs, "Estoque", "inventory", new String[]{"Atualizar", "Exportar estoque CSV"}, new Runnable[]{this::refreshAll, this::exportInventory});
        addTab(tabs, "Movimentacoes", "movements", new String[]{"Atualizar", "Exportar CSV"}, new Runnable[]{this::refreshAll, this::exportMovements});
        addTab(tabs, "Lotes", "lots", new String[]{"Atualizar lotes"}, new Runnable[]{this::refreshAll});
        root.add(tabs, BorderLayout.CENTER); setContentPane(root);
        SwingUtilities.invokeLater(this::refreshAll);
    }

    private void addTab(JTabbedPane tabs, String title, String key, String[] labels, Runnable[] actions) {
        JPanel page = new JPanel(new BorderLayout(6, 6)); JPanel bar = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
        for (int i = 0; i < labels.length; i++) { final Runnable action = actions[i]; JButton b = new JButton(labels[i]); b.addActionListener(e -> runSafe(action)); bar.add(b); }
        page.add(bar, BorderLayout.NORTH); JTable table = new JTable(new DefaultTableModel()); table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF); table.setFillsViewportHeight(true); table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION); table.setRowHeight(24);
        page.add(new JScrollPane(table), BorderLayout.CENTER); grids.put(key, table); tabs.addTab(title, page);
    }
    private void runSafe(Runnable r) { try { r.run(); refreshAll(); } catch (Exception ex) { JOptionPane.showMessageDialog(this, ex.getMessage(), "StockFlow", JOptionPane.WARNING_MESSAGE); } }
    private int selectedId(String key) { int row=grids.get(key).getSelectedRow(); if(row<0)throw new IllegalArgumentException("Selecione um registro na tabela."); return Integer.parseInt(grids.get(key).getValueAt(row,0).toString()); }
    private void show(String key, List<Map<String,Object>> rows) {
        JTable table=grids.get(key); DefaultTableModel model=new DefaultTableModel();
        if(!rows.isEmpty()){for(String col:rows.get(0).keySet())model.addColumn(col);for(Map<String,Object> r:rows)model.addRow(r.values().toArray());}
        table.setModel(model); table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);
    }
    private void refreshAll() {
        show("products",service.products(true)); show("suppliers",service.suppliers(true));
        var inventory=service.inventory(true);
        show("stock",inventory.stream().filter(r->"1".equals(Objects.toString(r.get("active"),"0"))).toList());
        show("overview",inventory); show("inventory",inventory);
        show("reservations",service.reservations()); show("blocks",service.blocks()); show("holds",service.holds());
        show("movements",service.movements()); show("lots",service.lots());
    }

    private Map<String,String> form(String title, String[] labels, String[] initial, Map<Integer,String[]> choices) {
        JPanel p=new JPanel(new GridLayout(labels.length,2,8,7)); List<JComponent> comps=new ArrayList<>();
        for(int i=0;i<labels.length;i++){p.add(new JLabel(labels[i]));JComponent c;if(choices.containsKey(i)){JComboBox<String> box=new JComboBox<>(choices.get(i));if(initial[i]!=null)box.setSelectedItem(initial[i]);c=box;}else{JTextField field=new JTextField(initial[i]==null?"":initial[i],22);c=field;}comps.add(c);p.add(c);}
        int res=JOptionPane.showConfirmDialog(this,p,title,JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(res!=JOptionPane.OK_OPTION)return null;
        Map<String,String> out=new LinkedHashMap<>();for(int i=0;i<labels.length;i++){JComponent c=comps.get(i);out.put(labels[i],c instanceof JTextField t?t.getText():Objects.toString(((JComboBox<?>)c).getSelectedItem(),""));}return out;
    }
    private record ProductChoice(String label,int id){}
    private List<ProductChoice> productChoices(){return service.products(false).stream().map(r->new ProductChoice(r.get("id")+" - "+r.get("sku")+" - "+r.get("name"),Integer.parseInt(r.get("id").toString()))).toList();}
    private static Map<Integer,String[]> choice(int index,String...values){return Map.of(index,values);}
    private static Map<Integer,String[]> choices(int firstIndex,String[] firstValues,int secondIndex,String...secondValues){return Map.of(firstIndex,firstValues,secondIndex,secondValues);}
    private static int choiceId(String value,List<ProductChoice> options){return options.stream().filter(x->x.label().equals(value)).findFirst().orElseThrow().id();}

    private void addProduct(){var d=form("Cadastrar produto",new String[]{"SKU","Nome","Categoria","Unidade","Capacidade maxima","Preco unitario"},new String[]{"","","MEAT","UN","100","0"},choice(2,CATEGORIES));if(d!=null)service.addProduct(d.get("SKU"),d.get("Nome"),d.get("Categoria"),d.get("Unidade"),num(d.get("Capacidade maxima")),num(d.get("Preco unitario")));}
    private void editProduct(){int id=selectedId("products");var p=service.product(id);var d=form("Editar produto",new String[]{"Nome","Categoria","Unidade","Capacidade maxima","Preco unitario"},new String[]{s(p,"name"),s(p,"category"),s(p,"unit"),s(p,"max_quantity"),s(p,"unit_price")},choice(1,CATEGORIES));if(d!=null)service.updateProduct(id,d.get("Nome"),d.get("Categoria"),d.get("Unidade"),num(d.get("Capacidade maxima")),num(d.get("Preco unitario")),Integer.parseInt(s(p,"active"))!=0);}
    private boolean confirmAfterDelay(){JDialog dialog=new JDialog(this,"Confirmar reativacao",true);dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);JPanel panel=new JPanel(new BorderLayout(8,8));panel.setBorder(BorderFactory.createEmptyBorder(14,14,14,14));panel.add(new JLabel("A reativacao sera liberada apos cinco segundos. Confirme para ativar o produto."),BorderLayout.CENTER);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT));JButton confirm=new JButton("Aguarde 5 segundos");confirm.setEnabled(false);JButton cancel=new JButton("Cancelar");actions.add(cancel);actions.add(confirm);panel.add(actions,BorderLayout.SOUTH);dialog.setContentPane(panel);dialog.pack();dialog.setLocationRelativeTo(this);final boolean[] accepted={false};final int[] remaining={5};javax.swing.Timer timer=new javax.swing.Timer(1000,e->{remaining[0]--;if(remaining[0]<=0){((javax.swing.Timer)e.getSource()).stop();confirm.setText("Confirmar reativacao");confirm.setEnabled(true);}else confirm.setText("Aguarde "+remaining[0]+" segundos");});confirm.addActionListener(e->{accepted[0]=true;dialog.dispose();});cancel.addActionListener(e->dialog.dispose());dialog.addWindowListener(new java.awt.event.WindowAdapter(){@Override public void windowClosed(java.awt.event.WindowEvent e){timer.stop();}});timer.start();dialog.setVisible(true);return accepted[0];}
    private void reactivateProduct(){int id=selectedId("products");var p=service.product(id);if(Integer.parseInt(s(p,"active"))!=0){JOptionPane.showMessageDialog(this,"O produto selecionado ja esta ativo.");return;}if(confirmAfterDelay())service.updateProduct(id,s(p,"name"),s(p,"category"),s(p,"unit"),num(s(p,"max_quantity")),num(s(p,"unit_price")),true);}
    private void deactivateProduct(){int id=selectedId("products");var p=service.product(id);if(JOptionPane.showConfirmDialog(this,"Desativar o produto selecionado?","Confirmar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)service.updateProduct(id,s(p,"name"),s(p,"category"),s(p,"unit"),num(s(p,"max_quantity")),num(s(p,"unit_price")),false);}
    private void addSupplier(){var d=form("Cadastrar fornecedor",new String[]{"Nome","Documento","E-mail","Telefone"},new String[]{"","","",""},Map.of());if(d!=null)service.addSupplier(d.get("Nome"),d.get("Documento"),d.get("E-mail"),d.get("Telefone"));}
    private void editSupplier(){int id=selectedId("suppliers");var p=service.supplier(id);var d=form("Editar fornecedor",new String[]{"Nome","Documento","E-mail","Telefone","Ativo (1/0)"},new String[]{s(p,"name"),s(p,"document"),s(p,"email"),s(p,"phone"),s(p,"active")},Map.of());if(d!=null)service.updateSupplier(id,d.get("Nome"),d.get("Documento"),d.get("E-mail"),d.get("Telefone"),d.get("Ativo (1/0)").equals("1"));}
    private void requestReplenishment(){int supplierId=selectedId("suppliers");var supplier=service.supplier(supplierId);if(Integer.parseInt(s(supplier,"active"))==0)throw new IllegalStateException("Nao e possivel solicitar reposicao a fornecedor inativo.");var products=productChoices();if(products.isEmpty())throw new IllegalStateException("Cadastre um produto ativo antes de solicitar reposicao.");String[] options=products.stream().map(ProductChoice::label).toArray(String[]::new);var d=form("Solicitar reposicao",new String[]{"Produto","Quantidade"},new String[]{options[0],"1"},choice(0,options));if(d!=null)service.createReservation(choiceId(d.get("Produto"),products),"REPLENISHMENT",num(d.get("Quantidade")),"Fornecedor: "+s(supplier,"name"),"");}
    private void receipt(){var ps=productChoices();if(ps.isEmpty())throw new IllegalStateException("Cadastre um produto ativo primeiro.");String[] options=ps.stream().map(ProductChoice::label).toArray(String[]::new);var d=form("Registrar entrada",new String[]{"Produto","Quantidade","Codigo do lote","Recebimento (AAAA-MM-DD)","Validade (AAAA-MM-DD ou vazio)","ID do fornecedor (opcional)","Custo unitario","ID da reserva de reposicao (opcional)"},new String[]{options[0],"1","",LocalDate.now().toString(),"","","0",""},choice(0,options));if(d!=null)service.receipt(choiceId(d.get("Produto"),ps),num(d.get("Quantidade")),d.get("Codigo do lote"),d.get("Recebimento (AAAA-MM-DD)"),d.get("Validade (AAAA-MM-DD ou vazio)"),intOrNull(d.get("ID do fornecedor (opcional)")),num(d.get("Custo unitario")),intOrNull(d.get("ID da reserva de reposicao (opcional)")));}
    private void issue(){var ps=productChoices();if(ps.isEmpty())throw new IllegalStateException("Nao ha produtos ativos.");String[] options=ps.stream().map(ProductChoice::label).toArray(String[]::new);var d=form("Registrar saida",new String[]{"Produto","Quantidade","Observacoes"},new String[]{options[0],"1",""},choice(0,options));if(d!=null)service.issue(choiceId(d.get("Produto"),ps),num(d.get("Quantidade")),d.get("Observacoes"));}
    private void addReservation(){var ps=productChoices();if(ps.isEmpty())throw new IllegalStateException("Nao ha produtos ativos.");String[] options=ps.stream().map(ProductChoice::label).toArray(String[]::new);var d=form("Nova reserva",new String[]{"Produto","Tipo","Quantidade","Referencia / pedido / fornecedor","Expiracao (AAAA-MM-DD HH:MM ou vazio)"},new String[]{options[0],"CUSTOMER","1","",""},choices(0,options,1,"CUSTOMER","REPLENISHMENT"));if(d!=null)service.createReservation(choiceId(d.get("Produto"),ps),d.get("Tipo"),num(d.get("Quantidade")),d.get("Referencia / pedido / fornecedor"),d.get("Expiracao (AAAA-MM-DD HH:MM ou vazio)"));}
    private void confirmReservation(){service.confirmReservation(selectedId("reservations"));}
    private void cancelReservation(){service.cancelReservation(selectedId("reservations"));}
    private void addBlock(){var ps=productChoices();if(ps.isEmpty())throw new IllegalStateException("Nao ha produtos ativos.");String[] options=ps.stream().map(ProductChoice::label).toArray(String[]::new);var d=form("Criar bloqueio operacional",new String[]{"Produto","Operacao","Motivo"},new String[]{options[0],"OUTBOUND",""},choices(0,options,1,"INBOUND","OUTBOUND","BOTH"));if(d!=null)service.addBlock(choiceId(d.get("Produto"),ps),d.get("Operacao"),d.get("Motivo"));}
    private void releaseBlock(){int id=selectedId("blocks");var d=form("Liberar bloqueio",new String[]{"Responsavel pela liberacao"},new String[]{""},Map.of());if(d!=null)service.releaseBlock(id,d.get("Responsavel pela liberacao"));}
    private void addHold(){var ps=productChoices();if(ps.isEmpty())throw new IllegalStateException("Nao ha produtos ativos.");String[] options=ps.stream().map(ProductChoice::label).toArray(String[]::new);var d=form("Criar bloqueio fisico",new String[]{"Produto","Quantidade","Motivo"},new String[]{options[0],"1",""},choice(0,options));if(d!=null)service.addHold(choiceId(d.get("Produto"),ps),num(d.get("Quantidade")),d.get("Motivo"));}
    private void releaseHold(){int id=selectedId("holds");var d=form("Liberar bloqueio fisico",new String[]{"Responsavel pela liberacao"},new String[]{""},Map.of());if(d!=null)service.releaseHold(id,d.get("Responsavel pela liberacao"));}
    private void exportInventory(){exportCsv(service.inventory(true),"stockflow_estoque.csv");}
    private void exportMovements(){exportCsv(service.movements(),"stockflow_movimentacoes.csv");}
    private void exportCsv(List<Map<String,Object>> rows,String name){if(rows.isEmpty()){JOptionPane.showMessageDialog(this,"Nao ha dados para exportar.");return;}JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new File(name));if(chooser.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try(Writer w=new OutputStreamWriter(new FileOutputStream(chooser.getSelectedFile()),StandardCharsets.UTF_8)){w.write('\uFEFF');var headers=rows.get(0).keySet();w.write(String.join(";",headers.stream().map(StockFlowApp::csv).toList())+"\r\n");for(var row:rows)w.write(String.join(";",row.values().stream().map(x->csv(Objects.toString(x,""))).toList())+"\r\n");JOptionPane.showMessageDialog(this,"CSV exportado com sucesso.");}catch(IOException ex){throw new IllegalStateException("Falha ao gravar CSV: "+ex.getMessage(),ex);}}
    private static String csv(String v){return "\""+v.replace("\"","\"\"")+"\"";}
    private static BigDecimal num(String value){return new BigDecimal(value.trim().replace(',','.'));}
    private static Integer intOrNull(String value){return value==null||value.isBlank()?null:Integer.valueOf(value.trim());}
    private static String s(Map<String,Object> map,String key){return Objects.toString(map.get(key),"");}

    public static void main(String[] args){SwingUtilities.invokeLater(()->new StockFlowApp().setVisible(true));}

    private static final class StockService {
        private final String url;
        private static final BigDecimal ZERO=BigDecimal.ZERO, HUNDRED=new BigDecimal("100");
        private static final Map<String,Integer> ENTRY_AGE=Map.of("MEAT",5,"FRUIT",15,"LEGUME",15,"GREENS",15,"DAIRY",20,"CEREAL",30);
        private static final Map<String,Integer> ENTRY_MIN=Map.of("MEAT",2,"FRUIT",10,"LEGUME",10,"GREENS",10,"DAIRY",15,"CEREAL",30);
        private static final Map<String,Integer> OUT_AGE=Map.of("MEAT",6,"FRUIT",20,"LEGUME",20,"GREENS",20,"DAIRY",25,"CEREAL",40);
        private static final Map<String,Integer> OUT_BLOCK=Map.of("MEAT",6,"FRUIT",25,"LEGUME",25,"GREENS",25,"DAIRY",25,"CEREAL",40);
        StockService(){Path db=Path.of("stockflow.db").toAbsolutePath();url="jdbc:sqlite:"+db;try(Connection c=open();Statement s=c.createStatement()){for(String statement:SCHEMA.split(";")){if(!statement.isBlank())s.execute(statement.trim());}}catch(SQLException e){throw failure(e);}}
        private Connection open()throws SQLException{Connection c=DriverManager.getConnection(url);try(Statement s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");s.execute("PRAGMA busy_timeout=20000");}return c;}
        private static final String SCHEMA="""
            CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,category TEXT NOT NULL,unit TEXT NOT NULL,max_quantity NUMERIC NOT NULL,unit_price NUMERIC NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
            CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,document TEXT UNIQUE,email TEXT,phone TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
            CREATE TABLE IF NOT EXISTS inventory_balances(product_id INTEGER PRIMARY KEY REFERENCES products(id),on_hand_quantity NUMERIC NOT NULL DEFAULT 0,reserved_outbound NUMERIC NOT NULL DEFAULT 0,reserved_inbound NUMERIC NOT NULL DEFAULT 0,held_quantity NUMERIC NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
            CREATE TABLE IF NOT EXISTS inventory_lots(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL REFERENCES products(id),supplier_id INTEGER REFERENCES suppliers(id),batch_code TEXT NOT NULL,received_at TEXT NOT NULL,expiration_date TEXT,received_quantity NUMERIC NOT NULL,remaining_quantity NUMERIC NOT NULL,unit_cost NUMERIC NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
            CREATE INDEX IF NOT EXISTS ix_lots_product_received ON inventory_lots(product_id,received_at);
            CREATE TABLE IF NOT EXISTS stock_operations(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL REFERENCES products(id),operation_type TEXT NOT NULL,idempotency_key TEXT UNIQUE,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
            CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,operation_id INTEGER NOT NULL REFERENCES stock_operations(id),product_id INTEGER NOT NULL REFERENCES products(id),lot_id INTEGER NOT NULL REFERENCES inventory_lots(id),movement_type TEXT NOT NULL,quantity NUMERIC NOT NULL,occurred_at TEXT DEFAULT CURRENT_TIMESTAMP,notes TEXT);
            CREATE TABLE IF NOT EXISTS reservations(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL REFERENCES products(id),reservation_type TEXT NOT NULL,quantity NUMERIC NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',reference TEXT,expires_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,released_at TEXT);
            CREATE INDEX IF NOT EXISTS ix_reservations_product_status ON reservations(product_id,status);
            CREATE TABLE IF NOT EXISTS reservation_allocations(id INTEGER PRIMARY KEY AUTOINCREMENT,reservation_id INTEGER NOT NULL REFERENCES reservations(id),lot_id INTEGER NOT NULL REFERENCES inventory_lots(id),quantity NUMERIC NOT NULL);
            CREATE TABLE IF NOT EXISTS operation_blocks(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL REFERENCES products(id),operation_type TEXT NOT NULL,reason TEXT NOT NULL,source TEXT NOT NULL DEFAULT 'MANUAL',status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT DEFAULT CURRENT_TIMESTAMP,released_at TEXT,released_by TEXT);
            CREATE TABLE IF NOT EXISTS stock_holds(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL REFERENCES products(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT DEFAULT CURRENT_TIMESTAMP,released_at TEXT,released_by TEXT);
            CREATE TABLE IF NOT EXISTS stock_hold_allocations(id INTEGER PRIMARY KEY AUTOINCREMENT,hold_id INTEGER NOT NULL REFERENCES stock_holds(id),lot_id INTEGER NOT NULL REFERENCES inventory_lots(id),quantity NUMERIC NOT NULL);
            """;
        private static RuntimeException failure(Exception e){return new IllegalStateException("Operacao nao concluida: "+e.getMessage(),e);}
        private static BigDecimal n(Object v){return v==null?ZERO:new BigDecimal(v.toString());}
        private static Object nil(String s){return s==null||s.isBlank()?null:s.trim();}
        private static void bind(PreparedStatement p,Object...values)throws SQLException{for(int i=0;i<values.length;i++)p.setObject(i+1,values[i]);}
        private static int exec(Connection c,String sql,Object...values)throws SQLException{try(PreparedStatement p=c.prepareStatement(sql)){bind(p,values);return p.executeUpdate();}}
        private static Object scalar(Connection c,String sql,Object...values)throws SQLException{try(PreparedStatement p=c.prepareStatement(sql)){bind(p,values);try(ResultSet r=p.executeQuery()){return r.next()?r.getObject(1):null;}}}
        private static List<Map<String,Object>> query(Connection c,String sql,Object...values)throws SQLException{try(PreparedStatement p=c.prepareStatement(sql)){bind(p,values);try(ResultSet r=p.executeQuery()){List<Map<String,Object>> out=new ArrayList<>();ResultSetMetaData md=r.getMetaData();while(r.next()){Map<String,Object> row=new LinkedHashMap<>();for(int i=1;i<=md.getColumnCount();i++)row.put(md.getColumnLabel(i),r.getObject(i));out.add(row);}return out;}}}
        private static Map<String,Object> one(Connection c,String sql,Object...values)throws SQLException{var r=query(c,sql,values);if(r.isEmpty())throw new IllegalArgumentException("Registro nao encontrado.");return r.get(0);}
        private static int age(String d){int a=(int)(LocalDate.now().toEpochDay()-LocalDate.parse(d).toEpochDay());if(a<0)throw new IllegalArgumentException("Data de recebimento nao pode estar no futuro.");return a;}
        private static BigDecimal pct(Object q,Object max){BigDecimal m=n(max);if(m.signum()<=0)throw new IllegalArgumentException("Capacidade maxima invalida.");return n(q).divide(m,8,java.math.RoundingMode.HALF_UP).multiply(HUNDRED);}
        private static String status(BigDecimal p){return p.compareTo(new BigDecimal("80"))>=0?"ALTO":p.compareTo(new BigDecimal("50"))>=0?"ACEITAVEL":p.compareTo(new BigDecimal("25"))>=0?"BAIXO":"CRITICO";}
        private static String quality(int a){return a<=10?"OTIMA":a<=19?"BOA":a<=30?"BAIXA":"PROIBIDO_CONSUMO";}
        private static String lowStockRecencyBlock(BigDecimal percentage,Integer latest){if(percentage.compareTo(new BigDecimal("25"))>=0||latest==null)return null;if(latest<3)return "Saida bloqueada: estoque abaixo de 25% e ultima remessa ha menos de 3 dias.";if(latest>31)return "Saida bloqueada: estoque abaixo de 25% e ultima remessa ha mais de 31 dias.";return null;}
        private Map<String,Object> product(Connection c,int id,boolean active)throws SQLException{var p=one(c,"SELECT * FROM products WHERE id=?",id);if(active&&n(p.get("active")).signum()==0)throw new IllegalArgumentException("Produto inativo; operacoes de estoque nao sao permitidas.");return p;}
        private Map<String,Object> balance(Connection c,int id)throws SQLException{return one(c,"SELECT * FROM inventory_balances WHERE product_id=?",id);}
        private Integer latestAge(Connection c,int id)throws SQLException{Object d=scalar(c,"SELECT MAX(received_at) FROM inventory_lots WHERE product_id=?",id);return d==null?null:age(d.toString());}
        private Map<String,Object> manualBlock(Connection c,int id,String op)throws SQLException{var rs=query(c,"SELECT * FROM operation_blocks WHERE product_id=? AND status='ACTIVE' AND operation_type IN (?, 'BOTH') ORDER BY id LIMIT 1",id,op);return rs.isEmpty()?null:rs.get(0);}
        private record Lot(int id,String code,String received,String expiration,BigDecimal remaining){}
        private List<Lot> lots(Connection c,int id)throws SQLException{return query(c,"SELECT * FROM inventory_lots WHERE product_id=? AND remaining_quantity>0 ORDER BY CASE WHEN expiration_date IS NULL THEN 1 ELSE 0 END,expiration_date,received_at,id",id).stream().map(r->new Lot(((Number)r.get("id")).intValue(),r.get("batch_code").toString(),r.get("received_at").toString(),Objects.toString(r.get("expiration_date"),null),n(r.get("remaining_quantity")))).toList();}
        private Map<Integer,BigDecimal> free(Connection c,List<Lot> lots)throws SQLException{Map<Integer,BigDecimal> f=new HashMap<>();for(Lot l:lots)f.put(l.id(),l.remaining());if(lots.isEmpty())return f;String ids=String.join(",",lots.stream().map(x->Integer.toString(x.id())).toList());for(var r:query(c,"SELECT ra.lot_id,SUM(ra.quantity) q FROM reservation_allocations ra JOIN reservations rv ON rv.id=ra.reservation_id WHERE ra.lot_id IN ("+ids+") AND rv.status='ACTIVE' AND rv.reservation_type='CUSTOMER' GROUP BY ra.lot_id")){int id=((Number)r.get("lot_id")).intValue();f.put(id,f.get(id).subtract(n(r.get("q"))));}for(var r:query(c,"SELECT ha.lot_id,SUM(ha.quantity) q FROM stock_hold_allocations ha JOIN stock_holds h ON h.id=ha.hold_id WHERE ha.lot_id IN ("+ids+") AND h.status='ACTIVE' GROUP BY ha.lot_id")){int id=((Number)r.get("lot_id")).intValue();f.put(id,f.get(id).subtract(n(r.get("q"))));}f.replaceAll((k,v)->v.max(ZERO));return f;}
        private void inboundCheck(Connection c,Map<String,Object> p,Map<String,Object> b,BigDecimal q,Map<String,Object> reservation)throws SQLException{int id=((Number)p.get("id")).intValue();Integer latest=latestAge(c,id);BigDecimal per=pct(b.get("on_hand_quantity"),p.get("max_quantity"));var block=manualBlock(c,id,"INBOUND");if(block!=null)throw new IllegalArgumentException("Entrada bloqueada manualmente: "+block.get("reason"));if(per.compareTo(new BigDecimal("85"))>0)throw new IllegalArgumentException("Estoque acima de 85% da capacidade maxima.");String cat=p.get("category").toString();if(per.compareTo(new BigDecimal("25"))>=0&&latest!=null&&latest<ENTRY_MIN.getOrDefault(cat,3))throw new IllegalArgumentException("Entrada bloqueada pelo intervalo minimo da categoria.");if(!(per.compareTo(new BigDecimal("60"))<0||(latest!=null&&latest>ENTRY_AGE.getOrDefault(cat,20))))throw new IllegalArgumentException("Entrada nao autorizada pela regra de estoque e idade.");BigDecimal release=ZERO;if(reservation!=null){if(!"ACTIVE".equals(reservation.get("status"))||!"REPLENISHMENT".equals(reservation.get("reservation_type")))throw new IllegalArgumentException("Reserva nao ativa ou nao e de reposicao.");if(n(reservation.get("quantity")).compareTo(q)<0)throw new IllegalArgumentException("Entrada excede quantidade da reserva.");release=q;}if(n(b.get("on_hand_quantity")).add(n(b.get("reserved_inbound"))).subtract(release).add(q).compareTo(n(p.get("max_quantity")))>0)throw new IllegalArgumentException("Entrada excede a capacidade maxima.");}
        private List<Lot> eligible(Connection c,Map<String,Object> p,Map<String,Object> b,boolean checkManual)throws SQLException{int id=((Number)p.get("id")).intValue();BigDecimal per=pct(b.get("on_hand_quantity"),p.get("max_quantity"));Integer latest=latestAge(c,id);String recencyBlock=lowStockRecencyBlock(per,latest);if(recencyBlock!=null)throw new IllegalArgumentException(recencyBlock);if(per.compareTo(new BigDecimal("15"))<=0)throw new IllegalArgumentException("Saida nao permitida: estoque deve estar acima de 15%.");if(checkManual&&manualBlock(c,id,"OUTBOUND")!=null)throw new IllegalArgumentException("Saida bloqueada manualmente.");String cat=p.get("category").toString();List<Lot> out=new ArrayList<>();for(Lot l:lots(c,id)){int a=age(l.received());boolean exp=l.expiration()!=null&&LocalDate.parse(l.expiration()).isBefore(LocalDate.now());if(!exp&&!quality(a).equals("PROIBIDO_CONSUMO")&&a<=OUT_BLOCK.getOrDefault(cat,31)&&a<OUT_AGE.getOrDefault(cat,40))out.add(l);}return out;}
        private static List<Map.Entry<Lot,BigDecimal>> allocate(List<Lot> lots,Map<Integer,BigDecimal> free,BigDecimal q){List<Map.Entry<Lot,BigDecimal>> out=new ArrayList<>();BigDecimal remain=q;for(Lot l:lots){BigDecimal take=free.getOrDefault(l.id(),ZERO).min(remain);if(take.signum()>0){out.add(Map.entry(l,take));remain=remain.subtract(take);}if(remain.signum()==0)break;}if(remain.signum()>0)throw new IllegalArgumentException("Quantidade livre insuficiente em lotes elegiveis. Faltam "+remain);return out;}
        List<Map<String,Object>> products(boolean all){try(Connection c=open()){return query(c,"SELECT p.id,p.sku,p.name,p.category,p.unit,p.max_quantity,p.unit_price,p.active,b.on_hand_quantity FROM products p JOIN inventory_balances b ON b.product_id=p.id "+(all?"":"WHERE p.active=1 ")+"ORDER BY p.name");}catch(SQLException e){throw failure(e);}}
        Map<String,Object> product(int id){try(Connection c=open()){return product(c,id,false);}catch(SQLException e){throw failure(e);}}
        void addProduct(String sku,String name,String cat,String unit,BigDecimal max,BigDecimal price){if(sku.isBlank()||name.isBlank()||max.signum()<=0||price.signum()<0)throw new IllegalArgumentException("SKU, nome, capacidade e preco invalidos.");try(Connection c=open()){c.setAutoCommit(false);exec(c,"INSERT INTO products(sku,name,category,unit,max_quantity,unit_price,active) VALUES(?,?,?,?,?,?,1)",sku.trim(),name.trim(),cat,unit.trim().toUpperCase(),max,price);int id=((Number)scalar(c,"SELECT last_insert_rowid()")).intValue();exec(c,"INSERT INTO inventory_balances(product_id) VALUES(?)",id);c.commit();}catch(SQLException e){throw failure(e);}}
        void updateProduct(int id,String name,String cat,String unit,BigDecimal max,BigDecimal price,boolean active){if(name.isBlank()||!ENTRY_AGE.containsKey(cat)||max.signum()<=0||price.signum()<0)throw new IllegalArgumentException("Nome, categoria, capacidade ou preco invalidos.");try(Connection c=open()){c.setAutoCommit(false);var p=product(c,id,false);var b=balance(c,id);if(max.compareTo(n(b.get("on_hand_quantity")).add(n(b.get("reserved_inbound"))))<0)throw new IllegalArgumentException("Capacidade menor que estoque fisico mais reserva.");if(!unit.trim().equalsIgnoreCase(p.get("unit").toString())&&List.of("on_hand_quantity","reserved_outbound","reserved_inbound","held_quantity").stream().anyMatch(k->n(b.get(k)).signum()>0))throw new IllegalArgumentException("Nao pode alterar unidade com estoque/reserva/bloqueio ativo.");exec(c,"UPDATE products SET name=?,category=?,unit=?,max_quantity=?,unit_price=?,active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",name.trim(),cat,unit.trim().toUpperCase(),max,price,active?1:0,id);c.commit();}catch(SQLException e){throw failure(e);}}
        List<Map<String,Object>> suppliers(boolean all){try(Connection c=open()){return query(c,"SELECT id,name,document,email,phone,active FROM suppliers "+(all?"":"WHERE active=1 ")+"ORDER BY name");}catch(SQLException e){throw failure(e);}}
        Map<String,Object> supplier(int id){try(Connection c=open()){return one(c,"SELECT * FROM suppliers WHERE id=?",id);}catch(SQLException e){throw failure(e);}}
        void addSupplier(String name,String doc,String email,String phone){if(name.isBlank())throw new IllegalArgumentException("Informe o nome do fornecedor.");try(Connection c=open()){exec(c,"INSERT INTO suppliers(name,document,email,phone,active) VALUES(?,?,?,?,1)",name.trim(),nil(doc),nil(email),nil(phone));}catch(SQLException e){throw failure(e);}}
        void updateSupplier(int id,String name,String doc,String email,String phone,boolean active){if(name.isBlank())throw new IllegalArgumentException("Informe o nome do fornecedor.");try(Connection c=open()){exec(c,"UPDATE suppliers SET name=?,document=?,email=?,phone=?,active=? WHERE id=?",name.trim(),nil(doc),nil(email),nil(phone),active?1:0,id);}catch(SQLException e){throw failure(e);}}
        void receipt(int pid,BigDecimal q,String batch,String received,String expiration,Integer supplierId,BigDecimal cost,Integer reservationId){LocalDate rd=LocalDate.parse(received);LocalDate exp=expiration.isBlank()?null:LocalDate.parse(expiration);if(q.signum()<=0||cost.signum()<0||batch.isBlank()||rd.isAfter(LocalDate.now())||exp!=null&&exp.isBefore(rd))throw new IllegalArgumentException("Quantidade, lote, custo ou datas invalidas.");try(Connection c=open()){c.setAutoCommit(false);var p=product(c,pid,true);var b=balance(c,pid);Map<String,Object> r=reservationId==null?null:one(c,"SELECT * FROM reservations WHERE id=? AND product_id=?",reservationId,pid);if(supplierId!=null&&n(scalar(c,"SELECT COUNT(*) FROM suppliers WHERE id=? AND active=1",supplierId)).signum()==0)throw new IllegalArgumentException("Fornecedor inexistente ou inativo.");inboundCheck(c,p,b,q,r);exec(c,"INSERT INTO stock_operations(product_id,operation_type) VALUES(?,'INBOUND')",pid);int op=((Number)scalar(c,"SELECT last_insert_rowid()")).intValue();exec(c,"INSERT INTO inventory_lots(product_id,supplier_id,batch_code,received_at,expiration_date,received_quantity,remaining_quantity,unit_cost) VALUES(?,?,?,?,?,?,?,?)",pid,supplierId,batch.trim(),received,expiration.isBlank()?null:expiration,q,q,cost);int lot=((Number)scalar(c,"SELECT last_insert_rowid()")).intValue();exec(c,"INSERT INTO stock_movements(operation_id,product_id,lot_id,movement_type,quantity) VALUES(?,?,?,'INBOUND',?)",op,pid,lot,q);exec(c,"UPDATE inventory_balances SET on_hand_quantity=on_hand_quantity+?,version=version+1 WHERE product_id=?",q,pid);if(r!=null){BigDecimal left=n(r.get("quantity")).subtract(q);exec(c,"UPDATE inventory_balances SET reserved_inbound=reserved_inbound-? WHERE product_id=?",q,pid);exec(c,"UPDATE reservations SET quantity=?,status=?,released_at=CASE WHEN ?=0 THEN CURRENT_TIMESTAMP ELSE released_at END WHERE id=?",left,left.signum()==0?"CONFIRMED":"ACTIVE",left,reservationId);}c.commit();}catch(SQLException e){throw failure(e);}}
        void issue(int pid,BigDecimal q,String notes){if(q.signum()<=0)throw new IllegalArgumentException("Quantidade deve ser positiva.");try(Connection c=open()){c.setAutoCommit(false);var p=product(c,pid,true);var b=balance(c,pid);var eligible=eligible(c,p,b,true);var all=lots(c,pid);var allocation=allocate(eligible,free(c,all),q);exec(c,"INSERT INTO stock_operations(product_id,operation_type) VALUES(?,'OUTBOUND')",pid);int op=((Number)scalar(c,"SELECT last_insert_rowid()")).intValue();for(var a:allocation){exec(c,"UPDATE inventory_lots SET remaining_quantity=remaining_quantity-? WHERE id=?",a.getValue(),a.getKey().id());exec(c,"INSERT INTO stock_movements(operation_id,product_id,lot_id,movement_type,quantity,notes) VALUES(?,?,?,'OUTBOUND',?,?)",op,pid,a.getKey().id(),a.getValue(),nil(notes));}exec(c,"UPDATE inventory_balances SET on_hand_quantity=on_hand_quantity-?,version=version+1 WHERE product_id=?",q,pid);c.commit();}catch(SQLException e){throw failure(e);}}
        void createReservation(int pid,String kind,BigDecimal q,String ref,String expires){if(q.signum()<=0)throw new IllegalArgumentException("Quantidade deve ser positiva.");String exp=null;if(!expires.isBlank()){LocalDateTime dt=LocalDateTime.parse(expires.replace(' ','T'));if(!dt.isAfter(LocalDateTime.now()))throw new IllegalArgumentException("Expiracao deve estar no futuro.");exp=dt.toString().replace('T',' ');}try(Connection c=open()){c.setAutoCommit(false);var p=product(c,pid,true);var b=balance(c,pid);if(kind.equals("CUSTOMER")){var allowed=eligible(c,p,b,true);var all=lots(c,pid);var allocations=allocate(allowed,free(c,all),q);exec(c,"INSERT INTO reservations(product_id,reservation_type,quantity,status,reference,expires_at) VALUES(?,'CUSTOMER',?,'ACTIVE',?,?)",pid,q,nil(ref),exp);int rid=((Number)scalar(c,"SELECT last_insert_rowid()")).intValue();for(var a:allocations)exec(c,"INSERT INTO reservation_allocations(reservation_id,lot_id,quantity) VALUES(?,?,?)",rid,a.getKey().id(),a.getValue());exec(c,"UPDATE inventory_balances SET reserved_outbound=reserved_outbound+?,version=version+1 WHERE product_id=?",q,pid);}else{inboundCheck(c,p,b,q,null);if(n(b.get("on_hand_quantity")).add(n(b.get("reserved_inbound"))).add(q).compareTo(n(p.get("max_quantity")))>0)throw new IllegalArgumentException("Reserva de reposicao excede capacidade.");exec(c,"INSERT INTO reservations(product_id,reservation_type,quantity,status,reference,expires_at) VALUES(?,'REPLENISHMENT',?,'ACTIVE',?,?)",pid,q,nil(ref),exp);exec(c,"UPDATE inventory_balances SET reserved_inbound=reserved_inbound+?,version=version+1 WHERE product_id=?",q,pid);}c.commit();}catch(SQLException e){throw failure(e);}}
        List<Map<String,Object>> reservations(){try(Connection c=open()){return query(c,"SELECT r.id,p.sku,p.name product_name,r.reservation_type,r.quantity,r.status,r.reference,r.created_at FROM reservations r JOIN products p ON p.id=r.product_id ORDER BY r.created_at DESC");}catch(SQLException e){throw failure(e);}}
        void confirmReservation(int id){try(Connection c=open()){c.setAutoCommit(false);var r=one(c,"SELECT * FROM reservations WHERE id=?",id);if(!"ACTIVE".equals(r.get("status"))||!"CUSTOMER".equals(r.get("reservation_type")))throw new IllegalArgumentException("Somente reserva ativa de cliente pode ser confirmada.");int pid=((Number)r.get("product_id")).intValue();var p=product(c,pid,true);var b=balance(c,pid);BigDecimal per=pct(b.get("on_hand_quantity"),p.get("max_quantity"));Integer latest=latestAge(c,pid);if(per.compareTo(new BigDecimal("15"))<=0)throw new IllegalArgumentException("Saida nao permitida: estoque deve estar acima de 15%.");String recencyBlock=lowStockRecencyBlock(per,latest);if(recencyBlock!=null)throw new IllegalArgumentException(recencyBlock);if(manualBlock(c,pid,"OUTBOUND")!=null)throw new IllegalArgumentException("Saida bloqueada manualmente.");var allocations=query(c,"SELECT ra.quantity,l.id,l.batch_code,l.received_at,l.expiration_date,l.remaining_quantity FROM reservation_allocations ra JOIN inventory_lots l ON l.id=ra.lot_id WHERE ra.reservation_id=?",id);BigDecimal sum=allocations.stream().map(x->n(x.get("quantity"))).reduce(ZERO,BigDecimal::add);if(sum.compareTo(n(r.get("quantity")))!=0)throw new IllegalArgumentException("Alocacoes divergentes.");String cat=p.get("category").toString();exec(c,"INSERT INTO stock_operations(product_id,operation_type) VALUES(?,'OUTBOUND')",pid);int op=((Number)scalar(c,"SELECT last_insert_rowid()")).intValue();for(var a:allocations){int age=age(a.get("received_at").toString());String ex=Objects.toString(a.get("expiration_date"),null);boolean expired=ex!=null&&LocalDate.parse(ex).isBefore(LocalDate.now());boolean allowed=!expired&&!quality(age).equals("PROIBIDO_CONSUMO")&&age<=OUT_BLOCK.getOrDefault(cat,31)&&age<OUT_AGE.getOrDefault(cat,40);if(!allowed||n(a.get("remaining_quantity")).compareTo(n(a.get("quantity")))<0)throw new IllegalArgumentException("Lote nao atende mais as regras de saida: "+a.get("batch_code"));exec(c,"UPDATE inventory_lots SET remaining_quantity=remaining_quantity-? WHERE id=?",a.get("quantity"),a.get("id"));exec(c,"INSERT INTO stock_movements(operation_id,product_id,lot_id,movement_type,quantity,notes) VALUES(?,?,?,'OUTBOUND',?,?)",op,pid,a.get("id"),a.get("quantity"),"Confirmacao da reserva "+id);}exec(c,"UPDATE inventory_balances SET on_hand_quantity=on_hand_quantity-?,reserved_outbound=reserved_outbound-?,version=version+1 WHERE product_id=?",sum,sum,pid);exec(c,"UPDATE reservations SET status='CONFIRMED',released_at=CURRENT_TIMESTAMP WHERE id=?",id);c.commit();}catch(SQLException e){throw failure(e);}}
        void cancelReservation(int id){try(Connection c=open()){c.setAutoCommit(false);var r=one(c,"SELECT * FROM reservations WHERE id=?",id);if(!"ACTIVE".equals(r.get("status")))throw new IllegalArgumentException("Reserva ja encerrada.");String col="CUSTOMER".equals(r.get("reservation_type"))?"reserved_outbound":"reserved_inbound";exec(c,"UPDATE inventory_balances SET "+col+"="+col+"-?,version=version+1 WHERE product_id=?",r.get("quantity"),r.get("product_id"));exec(c,"UPDATE reservations SET status='CANCELLED',released_at=CURRENT_TIMESTAMP WHERE id=?",id);c.commit();}catch(SQLException e){throw failure(e);}}
        void addBlock(int pid,String type,String reason){if(reason.isBlank())throw new IllegalArgumentException("Informe o motivo.");try(Connection c=open()){product(c,pid,true);exec(c,"INSERT INTO operation_blocks(product_id,operation_type,reason,source,status) VALUES(?,?,?,'MANUAL','ACTIVE')",pid,type,reason.trim());}catch(SQLException e){throw failure(e);}}
        List<Map<String,Object>> blocks(){try(Connection c=open()){return query(c,"SELECT b.id,p.sku,p.name product_name,b.operation_type,b.reason,b.status,b.released_by FROM operation_blocks b JOIN products p ON p.id=b.product_id ORDER BY b.created_at DESC");}catch(SQLException e){throw failure(e);}}
        void releaseBlock(int id,String who){if(who.isBlank())throw new IllegalArgumentException("Informe o responsavel.");try(Connection c=open()){if(exec(c,"UPDATE operation_blocks SET status='RELEASED',released_at=CURRENT_TIMESTAMP,released_by=? WHERE id=? AND status='ACTIVE'",who.trim(),id)==0)throw new IllegalArgumentException("Bloqueio inexistente ou ja liberado.");}catch(SQLException e){throw failure(e);}}
        void addHold(int pid,BigDecimal q,String reason){if(q.signum()<=0||reason.isBlank())throw new IllegalArgumentException("Quantidade e motivo obrigatorios.");try(Connection c=open()){c.setAutoCommit(false);product(c,pid,true);var all=lots(c,pid);var allocations=allocate(all,free(c,all),q);exec(c,"INSERT INTO stock_holds(product_id,reason,status) VALUES(?,?,'ACTIVE')",pid,reason.trim());int hid=((Number)scalar(c,"SELECT last_insert_rowid()")).intValue();for(var a:allocations)exec(c,"INSERT INTO stock_hold_allocations(hold_id,lot_id,quantity) VALUES(?,?,?)",hid,a.getKey().id(),a.getValue());exec(c,"UPDATE inventory_balances SET held_quantity=held_quantity+?,version=version+1 WHERE product_id=?",q,pid);c.commit();}catch(SQLException e){throw failure(e);}}
        List<Map<String,Object>> holds(){try(Connection c=open()){return query(c,"SELECT h.id,p.sku,p.name product_name,COALESCE((SELECT SUM(a.quantity) FROM stock_hold_allocations a WHERE a.hold_id=h.id),0) quantity,h.reason,h.status,h.released_by FROM stock_holds h JOIN products p ON p.id=h.product_id ORDER BY h.created_at DESC");}catch(SQLException e){throw failure(e);}}
        void releaseHold(int id,String who){if(who.isBlank())throw new IllegalArgumentException("Informe o responsavel.");try(Connection c=open()){c.setAutoCommit(false);var h=one(c,"SELECT * FROM stock_holds WHERE id=?",id);if(!"ACTIVE".equals(h.get("status")))throw new IllegalArgumentException("Bloqueio fisico ja liberado.");Object total=scalar(c,"SELECT COALESCE(SUM(quantity),0) FROM stock_hold_allocations WHERE hold_id=?",id);exec(c,"UPDATE inventory_balances SET held_quantity=held_quantity-?,version=version+1 WHERE product_id=?",total,h.get("product_id"));exec(c,"UPDATE stock_holds SET status='RELEASED',released_at=CURRENT_TIMESTAMP,released_by=? WHERE id=?",who.trim(),id);c.commit();}catch(SQLException e){throw failure(e);}}
        List<Map<String,Object>> inventory(boolean all){try(Connection c=open()){var rows=query(c,"SELECT p.*,b.on_hand_quantity,b.reserved_outbound,b.reserved_inbound,b.held_quantity FROM products p JOIN inventory_balances b ON b.product_id=p.id "+(all?"":"WHERE p.active=1 ")+"ORDER BY p.name");List<Map<String,Object>> out=new ArrayList<>();for(var p:rows){BigDecimal per=pct(p.get("on_hand_quantity"),p.get("max_quantity"));BigDecimal avail=ZERO;try{var eligible=eligible(c,p,p,false);if(manualBlock(c,((Number)p.get("id")).intValue(),"OUTBOUND")==null){var allLots=lots(c,((Number)p.get("id")).intValue());var free=free(c,allLots);avail=eligible.stream().map(l->free.getOrDefault(l.id(),ZERO)).reduce(ZERO,BigDecimal::add);}}catch(RuntimeException ignored){}Map<String,Object> row=new LinkedHashMap<>();row.put("id",p.get("id"));row.put("sku",p.get("sku"));row.put("name",p.get("name"));row.put("category",p.get("category"));row.put("unit",p.get("unit"));row.put("active",p.get("active"));row.put("Quantidade em estoque",p.get("on_hand_quantity"));row.put("Capacidade",p.get("max_quantity"));row.put("Percentual",per.setScale(2,java.math.RoundingMode.HALF_UP)+"%");row.put("Classificacao",status(per));row.put("Disponivel para saida",avail);row.put("Reservado cliente",p.get("reserved_outbound"));row.put("Capacidade reservada",p.get("reserved_inbound"));row.put("Bloqueado fisico",p.get("held_quantity"));out.add(row);}return out;}catch(SQLException e){throw failure(e);}}
        List<Map<String,Object>> movements(){try(Connection c=open()){return query(c,"SELECT m.id,p.sku,p.name product_name,l.batch_code,m.movement_type,m.quantity,m.occurred_at,m.notes FROM stock_movements m JOIN products p ON p.id=m.product_id JOIN inventory_lots l ON l.id=m.lot_id ORDER BY m.occurred_at DESC,m.id DESC LIMIT 500");}catch(SQLException e){throw failure(e);}}
        List<Map<String,Object>> lots(){try(Connection c=open()){return query(c,"SELECT l.id,p.sku,p.name product_name,l.batch_code,s.name supplier_name,l.received_at,l.expiration_date,l.received_quantity,l.remaining_quantity,l.unit_cost FROM inventory_lots l JOIN products p ON p.id=l.product_id LEFT JOIN suppliers s ON s.id=l.supplier_id ORDER BY l.received_at DESC,l.id DESC LIMIT 500");}catch(SQLException e){throw failure(e);}}
    }
}
